// Functional testbench for fft64_top.
// Loads a pure 0.5-amplitude sine tone at bin 5 (tone_bin5.mem, generated by
// scratchpad/gen_test_tone.py) and checks that the FFT magnitude spectrum
// peaks at bin 5, matching the expected result required by Sec. 6.6
// (entradas, resultados esperados vs. obtidos). Cross-checked against a
// floating-point Python reference of the same algorithm
// (scratchpad/fft_reference.py): expected bin 5 = (0, -8192) in Q1.15,
// all other bins ~0.
`timescale 1ns / 1ps

module tb_fft64_top;

    reg clk = 0;
    reg reset = 1;
    reg enable = 1;
    reg wr_en = 0;
    reg [5:0] wr_addr = 0;
    reg signed [15:0] wr_data = 0;
    reg start = 0;
    wire busy, done, valid;
    // ready comeca em 0 (nao 1) de proposito: assim `done` fica de verdade
    // esperando o pulso de ready mais abaixo, em vez de ja ter caido antes
    // do teste de handshake sequer comecar (ver comentario perto do fim).
    reg ready = 0;
    reg [5:0] rd_addr = 0;
    wire signed [15:0] rd_re, rd_im;

    reg signed [15:0] tone [0:63];

    integer i;
    integer peak_bin;
    integer peak_mag;
    integer mag;
    integer errors = 0;

    fft64_top dut (
        .clk(clk), .reset(reset), .enable(enable),
        .wr_en(wr_en), .wr_addr(wr_addr), .wr_data(wr_data),
        .start(start), .busy(busy), .done(done),
        .valid(valid), .ready(ready),
        .rd_addr(rd_addr), .rd_re(rd_re), .rd_im(rd_im)
    );

    always #5 clk = ~clk; // 100 MHz sim clock (design targets 50 MHz)

    initial begin
        $readmemh("tb/tone_bin5.mem", tone);

        // reset
        repeat (3) @(posedge clk);
        reset = 0;
        @(posedge clk);

        // Load 64 samples in natural time order. Stimulus is changed 1ns
        // after each posedge (not at the edge itself) so it is stable for
        // the full period before the DUT's next synchronous sample --
        // avoids the classic same-edge testbench/DUT race on
        // wr_addr/wr_data. One extra edge after the loop lets the last
        // sample's write actually commit before wr_en drops.
        wr_en = 1;
        for (i = 0; i < 64; i = i + 1) begin
            @(posedge clk);
            #1;
            wr_addr = i[5:0];
            wr_data = tone[i];
        end
        @(posedge clk);
        #1;
        wr_en = 0;

        // run
        @(posedge clk);
        #1;
        start = 1;
        @(posedge clk);
        #1;
        start = 0;

        wait (done == 1'b1);
        @(posedge clk);

        // Scan bins 0..31 (real input -> conjugate-symmetric spectrum, only
        // the first half is independent) for the magnitude peak.
        peak_bin = -1;
        peak_mag = -1;
        for (i = 0; i < 32; i = i + 1) begin
            rd_addr = i[5:0];
            #1; // let the async read settle
            mag = (rd_re[15] ? -rd_re : rd_re) + (rd_im[15] ? -rd_im : rd_im); // |re|+|im| approx
            $display("bin %0d: re=%0d im=%0d  |mag|approx=%0d", i, rd_re, rd_im, mag);
            if (mag > peak_mag) begin
                peak_mag = mag;
                peak_bin = i;
            end
        end

        if (peak_bin == 5) begin
            $display("PASS: magnitude spectrum peaks at bin %0d as expected", peak_bin);
        end else begin
            $display("FAIL: expected peak at bin 5, got bin %0d", peak_bin);
            errors = errors + 1;
        end

        // ---- handshake ready (achado de revisao de codigo, 15/08/2026):
        // antes deste fix, `ready` nao era consumido em lugar nenhum e
        // `done` so caia com um novo start/wr_en -- nenhum testbench
        // exercitava isso porque ready ficava travado em 1 o tempo todo.
        // Verifica agora, de proposito (ready ficou em 0 desde o inicio):
        // done deve continuar 1 enquanto ready=0, e so cair 1 ciclo depois
        // de ready pulsar.
        repeat (3) @(posedge clk);
        if (done !== 1'b1) begin
            $display("FAIL handshake_ready: done caiu sem ready ter pulsado");
            errors = errors + 1;
        end else begin
            $display("PASS handshake_ready: done permanece 1 com ready=0 (3 ciclos)");
        end
        ready = 1;
        @(posedge clk); #1;
        if (done !== 1'b0) begin
            $display("FAIL handshake_ready: done nao caiu 1 ciclo apos ready pulsar");
            errors = errors + 1;
        end else begin
            $display("PASS handshake_ready: done cai 1 ciclo apos ready pulsar");
        end

        if (errors == 0)
            $display("ALL PASS");
        else
            $display("%0d FAILURE(S)", errors);
        $finish;
    end

endmodule
